PRAGMA foreign_keys=ON;
CREATE TABLE groups (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, login TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','admin','superadmin')), group_id TEXT REFERENCES groups(id) ON DELETE SET NULL, blocked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX idx_users_group ON users(group_id,role);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 1, reset_at INTEGER NOT NULL);
CREATE TABLE tests (id TEXT PRIMARY KEY, title TEXT NOT NULL, discipline TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', question_count INTEGER NOT NULL DEFAULT 10 CHECK(question_count BETWEEN 1 AND 200), pass_percent INTEGER NOT NULL DEFAULT 70 CHECK(pass_percent BETWEEN 0 AND 100), minutes INTEGER NOT NULL DEFAULT 30 CHECK(minutes BETWEEN 0 AND 240), max_attempts INTEGER NOT NULL DEFAULT 2 CHECK(max_attempts BETWEEN 1 AND 20), published INTEGER NOT NULL DEFAULT 0, proctor_mode TEXT NOT NULL DEFAULT 'warn' CHECK(proctor_mode IN ('off','log','warn','block')), proctor_limit INTEGER NOT NULL DEFAULT 3 CHECK(proctor_limit BETWEEN 1 AND 50), fullscreen INTEGER NOT NULL DEFAULT 0, show_result INTEGER NOT NULL DEFAULT 1, show_history INTEGER NOT NULL DEFAULT 1, demo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE questions (id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES tests(id) ON DELETE CASCADE, text TEXT NOT NULL, options_json TEXT NOT NULL, correct_id TEXT NOT NULL, content_hash TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(test_id,content_hash));
CREATE INDEX idx_questions_test ON questions(test_id,archived);
CREATE TABLE assignments (id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES tests(id), group_id TEXT REFERENCES groups(id), user_id TEXT REFERENCES users(id), starts_at TEXT, ends_at TEXT, max_attempts INTEGER NOT NULL DEFAULT 2 CHECK(max_attempts BETWEEN 1 AND 20), closed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, CHECK((group_id IS NOT NULL AND user_id IS NULL) OR (user_id IS NOT NULL AND group_id IS NULL)));
CREATE UNIQUE INDEX idx_assignment_group_unique ON assignments(test_id,group_id) WHERE group_id IS NOT NULL;
CREATE UNIQUE INDEX idx_assignment_user_unique ON assignments(test_id,user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_assignments_group ON assignments(group_id,closed);
CREATE INDEX idx_assignments_user ON assignments(user_id,closed);
CREATE TABLE attempts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), test_id TEXT NOT NULL REFERENCES tests(id), assignment_id TEXT NOT NULL REFERENCES assignments(id), test_title TEXT NOT NULL, student_name TEXT NOT NULL, group_name TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','expired','blocked')), started_at TEXT NOT NULL, deadline TEXT, finished_at TEXT, pass_percent INTEGER NOT NULL, question_snapshot_json TEXT NOT NULL, answer_key_json TEXT NOT NULL, answers_json TEXT NOT NULL DEFAULT '{}', version INTEGER NOT NULL DEFAULT 0, score INTEGER, percent REAL, passed INTEGER, proctor_mode TEXT NOT NULL, proctor_limit INTEGER NOT NULL, fullscreen INTEGER NOT NULL DEFAULT 0, show_result INTEGER NOT NULL DEFAULT 1, show_history INTEGER NOT NULL DEFAULT 1, proctor_epoch INTEGER NOT NULL DEFAULT 0, violation_count INTEGER NOT NULL DEFAULT 0, client_id TEXT, client_lease_until INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX idx_one_active_attempt ON attempts(user_id,test_id) WHERE status='active';
CREATE INDEX idx_attempts_user_test ON attempts(user_id,test_id,started_at);
CREATE INDEX idx_attempts_status ON attempts(status,deadline);
CREATE INDEX idx_attempts_finished ON attempts(finished_at DESC);
CREATE TABLE proctor_events (attempt_id TEXT NOT NULL REFERENCES attempts(id) ON DELETE CASCADE, epoch INTEGER NOT NULL, event_id TEXT NOT NULL, kind TEXT NOT NULL, occurred_at TEXT NOT NULL, received_at TEXT NOT NULL, returned_at TEXT, duration_ms INTEGER NOT NULL DEFAULT 0, question_code TEXT NOT NULL DEFAULT '', counted INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(attempt_id,epoch,event_id));
CREATE INDEX idx_proctor_journal ON proctor_events(attempt_id,epoch,occurred_at);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), action TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_audit_created ON audit_log(created_at DESC);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
